const raw = $json.text || $json.output || $json.response || '';

let cleaned = raw.trim();
cleaned = cleaned
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '');

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  return {
    json: {
      Idea: $('Get Pending Content Idea').item.json.Idea,
      "Main Query": '',
      Keywords: '',
      Status: 'Failed',
      "Error Log": `Keyword JSON parse failed: ${cleaned}`
    }
  };
}

return {
  json: {
    Idea: $('Get Pending Content Idea').item.json.Idea,
    "Main Query": parsed.main_query || '',
    Keywords: parsed.keywords || '',
    Status: 'Researching',
    "Error Log": ''
  }
};

const results = $json.organic_results || [];
const topResults = results.slice(0, 3);

const competitors = topResults.map(r => r.link).join(", ");

const competitorNotes = topResults.map((r, index) => {
  const title = r.title || '';
  const snippet = r.snippet || '';
  const link = r.link || '';
  return `${index + 1}. ${title} | ${snippet} | ${link}`;
}).join("\n\n");

return {
  json: {
    Idea: $('Save Keyword Research (Update Sheet)').item.json.Idea,
    "Main Query": $('Save Keyword Research (Update Sheet)').item.json["Main Query"],
    Keywords: $('Save Keyword Research (Update Sheet)').item.json.Keywords,
    Competitors: competitors,
    "Competitors Notes": competitorNotes,
    Status: 'Draft Generated',
    "Error Log": ''
  }
};

